function timestamp(line) {
  return line.match(/^(\d{4}-\d\d-\d\dT[\d:.]+Z)/)?.[1] || null;
}
export function parseLog(raw) {
  const source=String(raw).replace(/\u001b\[[0-9;]*m/g,'');
  const lines=source.split('\n');
  let report=null;
  const venues=new Map(), events=[], errors=[];
  let hasExplicitNotificationEvents=false;
  for (const line of lines) {
    for (const marker of ['SCAN_REPORT','SCAN_VENUE_COMPLETE','DASHBOARD_EVENT']) {
      const pos=line.indexOf(marker+' ');
      if (pos<0) continue;
      let item;
      try { item=JSON.parse(line.slice(pos+marker.length+1)); } catch { continue; }
      if (marker==='SCAN_REPORT') report=item;
      if (marker==='SCAN_VENUE_COMPLETE' && VENUES.includes(item.place)) venues.set(item.place,{...item,checkedAt:timestamp(line),complete:true});
      if (marker==='DASHBOARD_EVENT' && typeof item.event==='string') {
        const event={...item,at:item.at || timestamp(line)};
        if(item.event==='notification-failed')errors.push({category:item.reason==='input'?'input':'notification',message:'ntfy: '+redact(item.reason)+(item.status?' HTTP '+item.status:''),at:event.at});
        delete event.topic; delete event.token;
        events.push(event);
        if (item.event==='venue-progress' && VENUES.includes(item.place)) venues.set(item.place,{...item,checkedAt:event.at,complete:item.complete===true});
        if (['notification-accepted','notification-duplicate','notification-failed'].includes(item.event)) hasExplicitNotificationEvents=true;
      }
    }
    if (/Monitor failed:|##\[error\]|"type":\s*"requestfailed"|"type":\s*"pageerror"|"type":\s*"http"/.test(line)) {
      const message=redact(line.replace(/^\S+Z\s*/, ''));
      errors.push({category:classify(message),message,at:timestamp(line)});
    }
    if (line.includes('Confirmed available reception time:') && !events.some(e=>e.event==='opening-detected')) {
      events.push({event:'opening-detected',at:timestamp(line),message:redact(line.split('Confirmed available reception time:')[1]),legacy:true});
    }
    if (line.includes('Notification accepted by ntfy;') && !events.some(e=>e.event==='notification-accepted'&&e.kind==='test')) events.push({event:'notification-accepted',at:timestamp(line),kind:'test',legacy:true});
  }
  if (report?.venues) for (const v of report.venues) if (VENUES.includes(v.place)) venues.set(v.place,{...v,checkedAt:report.checkedAt,complete:true});
  const states=VENUES.map(place=>{
    const v=venues.get(place);
    return v ? {
      place,checkedAt:v.checkedAt,months:Array.isArray(v.months)?v.months:[],
      unknown:Array.isArray(v.unknown)?v.unknown:[],
      openings:Array.isArray(v.openings)?v.openings:[],
      candidateDatesChecked:Number(v.checkedDates)||0,
      complete:v.complete!==false,
      status:v.unknown?.length?'unchecked':v.openings?.length?'available':v.complete===false?'unconfirmed':'no-selectable-dates'
    } : {place,status:'unconfirmed',complete:false,months:[],unknown:[],openings:[]};
  });
  return {
    checkedAt:report?.checkedAt || null,
    venues:states,events:events.slice(-100),errors:errors.slice(-30),
    unverifiedDates:report?.unverifiedDates || states.flatMap(x=>x.unknown),
    duplicateHistory:hasExplicitNotificationEvents?'recorded':'unrecorded',
    allVenuesConfirmed:states.every(x=>x.complete && !x.unknown.length),
    notificationMeaning:'accepted-is-not-phone-received'
  };
}
function headers(env) {
  return {
    Accept:'application/vnd.github+json',
    'X-GitHub-Api-Version':'2026-03-10',
    'User-Agent':'tokyo-license-dashboard',
    ...(env.BOT_GITHUB_TOKEN?{Authorization:'Bearer '+env.BOT_GITHUB_TOKEN}:{})
  };
}
async function limitedText(response) {
  if (Number(response.headers.get('content-length')) > MAX_LOG_BYTES) throw new ServiceError('ログが取得上限を超えています。GitHubで確認してください。',413,'page');
  const reader=response.body?.getReader();
  if (!reader) return '';
  const chunks=[]; let size=0;
  try {
    for (;;) {
      const {value,done}=await reader.read(); if(done) break;
      size+=value.length;
      if(size>MAX_LOG_BYTES) {await reader.cancel(); throw new ServiceError('ログが取得上限を超えています。',413,'page');}
      chunks.push(value);
    }
  } finally {reader.releaseLock();}
  const merged=new Uint8Array(size);let offset=0;
  for(const c of chunks){merged.set(c,offset);offset+=c.length;}
  return new TextDecoder().decode(merged);
}
async function requestGitHub(path, env, options={}) {
  let response;
  const {allowLogRedirect,...fetchOptions}=options;
  try {
    response=await fetch(ROOT+path,{...fetchOptions,headers:{...headers(env),...options.headers},redirect:'manual',signal:AbortSignal.timeout(15000)});
  } catch(e) {throw new ServiceError('GitHubへの接続に失敗しました。',502,e.name==='TimeoutError'?'timeout':'network');}
  if(response.status>=300 && response.status<400 && !options.allowLogRedirect) throw new ServiceError('GitHubから予期しないリダイレクトが返りました。',502,'http');
  if(!response.ok && !(options.allowLogRedirect && response.status===302)) {
    const retry=response.headers.get('retry-after');
    throw new ServiceError('GitHub HTTP '+response.status+(response.status===403||response.status===429?'：権限または取得制限を確認してください。':''),response.status===429?429:502,'http',retry);
  }
  return response;
}
async function readGitHub(path, env) {return (await requestGitHub(path,env)).json();}
function decode64(value) {
  const binary=atob(value.replace(/\s/g,''));return new TextDecoder().decode(Uint8Array.from(binary,c=>c.charCodeAt(0)));
}
function encode64(value) {
  const bytes=new TextEncoder().encode(value);let result='';
  for (const b of bytes) result+=String.fromCharCode(b);
  return btoa(result);
}
export function safeRun(run) {
  return {
    id:run.id,title:run.display_title || run.name,status:run.status,conclusion:run.conclusion,
    startedAt:run.run_started_at || run.created_at,updatedAt:run.updated_at,url:run.html_url,
    mode:/\/ test-notification \//.test(run.display_title)?'test-notification':/\/ verify \//.test(run.display_title)?'verify':'scan',
    source:run.display_title?.startsWith('cloud-timer /')?'cloud-timer':'manual-or-verify',
    plannedAt:run.display_title?.match(/\/ (\d{4}-\d\d-\d\dT[\d:.]+Z)/)?.[1] || null
  };
}
function errorInfo(e){return {message:redact(e.message),category:e.category || 'network',retryAfter:e.retryAfter || null};}
async function resultOf(fn){try{return {ok:true,data:await fn()};}catch(e){return {ok:false,error:errorInfo(e)};}}
export function midnightWindow(now=Date.now()) {
  const date=new Date(now+9*3600000).toISOString().slice(0,10);
  const at=new Date(date+'T00:00:00+09:00');
  return {japanDate:date,utc:at.toISOString(),start:at.toISOString(),end:new Date(+at+30*60000).toISOString()};
}
async function loadRunDetail(id, env) {
  if(!env.BOT_GITHUB_TOKEN) throw new ServiceError('実行ログの取得用トークンが未設定です。実行結果のみ表示しています。',503,'connection');
  const run=await readGitHub('/actions/runs/'+id,env);
  if(run.path!=='.github/workflows/monitor.yml') throw new ServiceError('監視用ワークフロー以外のログは取得できません。',400,'input');
  if(run.status!=='completed') return {run:safeRun(run),pending:true,scan:null};
  const jobs=await readGitHub('/actions/runs/'+id+'/jobs?per_page=10',env);
  const job=jobs.jobs.find(x=>x.name==='monitor');
  if(!job) throw new ServiceError('monitorジョブが見つかりません。',404,'page');
  const response=await requestGitHub('/actions/jobs/'+job.id+'/logs',env,{allowLogRedirect:true});
  let logResponse=response;
  if(response.status===302) {
    const location=new URL(response.headers.get('location'));
    if(location.protocol!=='https:' || !/(^|\.)blob\.core\.windows\.net$|(^|\.)actions\.githubusercontent\.com$|(^|\.)githubusercontent\.com$/.test(location.hostname)) throw new ServiceError('ログの転送先を確認できません。',502,'http');
    // No Authorization header is forwarded to the signed log URL.
    logResponse=await fetch(location,{redirect:'manual',signal:AbortSignal.timeout(15000)});
    if(!logResponse.ok) throw new ServiceError('ログの取得に失敗しました：HTTP '+logResponse.status,502,'http');
  }
  return {run:safeRun(run),scan:parseLog(await limitedText(logResponse)),pending:false};
}
async function loadStatus(env,page=1) {
  const midnight=midnightWindow();
  const getRuns=p=>resultOf(async()=>{const r=await readGitHub('/actions/workflows/'+WORKFLOW+'/runs?per_page=30&page='+p,env);return {total:r.total_count,items:r.workflow_runs.map(safeRun),page:p};});
  const recentPromise=getRuns(1);
  const pagePromise=page===1?recentPromise:getRuns(page);
  const [repository,configuration,workflow,runs,midnightRun,lastFailure,recentRuns]=await Promise.all([
    resultOf(()=>readGitHub('',env)),
    resultOf(async()=>{const file=await readGitHub('/contents/'+CONFIG_PATH+'?ref=main',env);return {...parseConfig(decode64(file.content)),sha:file.sha};}),
    resultOf(()=>readGitHub('/actions/workflows/'+WORKFLOW,env)),
    pagePromise,
    resultOf(async()=>{const r=await readGitHub('/actions/workflows/'+WORKFLOW+'/runs?per_page=20&created='+encodeURIComponent(midnight.start+'..'+midnight.end),env);
      return {date:midnight.japanDate,run:r.workflow_runs.map(safeRun).find(x=>x.source==='cloud-timer'&&x.mode==='scan'&&x.plannedAt?.slice(0,16)===midnight.utc.slice(0,16)) || null};}),
    resultOf(async()=>{const r=await readGitHub('/actions/workflows/'+WORKFLOW+'/runs?status=failure&per_page=1',env);return r.workflow_runs[0]?safeRun(r.workflow_runs[0]):null;}),
    recentPromise
  ]);
  const safeRepository=repository.ok?{ok:true,data:{public:repository.data.private===false && repository.data.visibility==='public',name:repository.data.full_name,url:repository.data.html_url}}:repository;
  const safeWorkflow=workflow.ok?{ok:true,data:{state:workflow.data.state,path:workflow.data.path,url:workflow.data.html_url}}:workflow;
  const latest=recentRuns.ok?recentRuns.data.items.find(x=>x.source==='cloud-timer'&&x.mode==='scan'&&x.status==='completed'):null;
  const scan=latest?await resultOf(()=>loadRunDetail(latest.id,env)):{ok:false,error:{category:'unchecked',message:'完了した定時スキャンを取得できていません。'}};
  return {
    fetchedAt:new Date().toISOString(),repository:safeRepository,configuration,workflow:safeWorkflow,runs,recentRuns,midnight:midnightRun,lastFailure,scan,
    controls:{enabled:!!env.BOT_GITHUB_TOKEN && env.BOT_ALLOW_CONTROL==='true' && !!env.DB,tokenConfigured:!!env.BOT_GITHUB_TOKEN,dbConfigured:!!env.DB},
    cloudflare:{status:'inferred-only',plan:'unverified',endpoint:'disabled',description:'GitHubの外部起動実績とリポジトリ設定を照合。Cloudflare本番の設定・請求・配信ログは未接続。'},
    history:{source:'GitHub Actions retained logs',scope:'表示した実行のみ。全期間の件数ではありません。'}
  };
}
async function beginOperation(db,id,user,action) {
  const claim=await db.prepare('INSERT OR IGNORE INTO dashboard_operations (id, owner_id, action, state, created_at) VALUES (?, ?, ?, ?, ?)').bind(id,user,action,'pending',new Date().toISOString()).run();
  if(claim.meta.changes===1) return null;
  const existing=await db.prepare('SELECT owner_id, action, state, result FROM dashboard_operations WHERE id = ?').bind(id).first();
  if(!existing || existing.owner_id!==user || existing.action!==action) throw new ServiceError('操作IDが一致しません。',409,'input');
  if(existing.state==='done') return JSON.parse(existing.result);
  throw new ServiceError('この操作は受付済みです。再実行せず、実行履歴または設定を確認してください。',409,'operation-uncertain');
}
async function operate(request,env,user) {
  if(request.headers.get('origin')!==new URL(request.url).origin) return json({ok:false,error:{message:'同じサイトから操作してください。'}},403);
  if(!env.BOT_GITHUB_TOKEN || env.BOT_ALLOW_CONTROL!=='true' || !env.DB) return json({ok:false,error:{message:'操作用トークン・操作許可・履歴DBの接続を完了してください。'}},503);
  if(!request.headers.get('content-type')?.startsWith('application/json') || Number(request.headers.get('content-length')||0)>2048) return json({ok:false,error:{message:'入力形式が不正です。'}},400);
  const text=await request.text();
  if(text.length>2048) return json({ok:false,error:{message:'入力が長すぎます。'}},400);
  let body;try{body=JSON.parse(text);}catch{return json({ok:false,error:{message:'入力を読み取れません。'}},400);}
  const {action,id}=body;
  if(!['start','pause','stop-all','scan','test-notification'].includes(action) || !/^[a-f0-9-]{36}$/.test(id||'')) return json({ok:false,error:{message:'操作が不正です。'}},400);
  const previous=await beginOperation(env.DB,id,user,action);
  if(previous) return json({...previous,replayed:true});
  try {
    const repo=await readGitHub('',env);
    if(repo.private!==false || repo.visibility!=='public' || repo.full_name!==REPO) throw new ServiceError('無料条件を確認できません。公開リポジトリ以外への操作を停止しました。',409,'input');
    const wf=await readGitHub('/contents/.github/workflows/'+WORKFLOW+'?ref=main',env);
    const wfText=decode64(wf.content);
    const runnerLabels=[...wfText.matchAll(/^\s*runs-on:\s*([^\r\n#]+)/gm)].map(x=>x[1].trim());
    if(runnerLabels.length!==1 || runnerLabels[0]!=='ubuntu-24.04') throw new ServiceError('標準の無料Linux runnerを確認できないため操作を停止しました。',409,'input');
    let result;
    if(['start','pause','stop-all'].includes(action)) {
      const file=await readGitHub('/contents/'+CONFIG_PATH+'?ref=main',env);
      const content=nextConfig(decode64(file.content),action);
      if(content===decode64(file.content)) result={ok:true,state:'already-configured',action,message:'リポジトリ設定は既に指定の状態です。本番反映は実行履歴で確認してください。'};
      else {
        const saved=await (await requestGitHub('/contents/'+CONFIG_PATH,env,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({branch:'main',sha:file.sha,content:encode64(content),message:'Dashboard: '+action+' monitoring'})})).json();
        result={ok:true,state:'configuration-saved',action,commit:saved.commit.sha,url:saved.commit.html_url,message:'設定を保存しました。CloudflareのGit連携による配信完了と次回実行を確認するまで、本番反映は未確認です。'};
      }
    } else {
      const mode=action==='scan'?'scan':'test-notification';
      const response=await requestGitHub('/actions/workflows/'+WORKFLOW+'/dispatches',env,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ref:'main',inputs:{mode,source:'manual',scheduled_at:new Date().toISOString()}})});
      let receipt=null;
      if(response.status===200){receipt=await response.json();if(!Number.isSafeInteger(receipt.workflow_run_id)||receipt.workflow_run_id<=0)throw new ServiceError('起動結果が不明です。再送せずGitHubで確認してください。',502,'operation-uncertain');}
      else if(response.status!==204) throw new ServiceError('起動結果が不明です。実行履歴を確認してください。',502,'operation-uncertain');
      result={ok:true,state:'accepted',action,runId:receipt?.workflow_run_id || null,message:mode==='scan'?'スキャンの起動を受け付けました。完了結果は実行履歴で確認してください。':'通知テストの起動を受け付けました。ntfy受付とスマートフォンの受信をそれぞれ確認してください。'};
    }
    await env.DB.prepare('UPDATE dashboard_operations SET state = ?, result = ? WHERE id = ?').bind('done',JSON.stringify(result),id).run();
    return json(result);
  } catch(e) {
    await env.DB.prepare('UPDATE dashboard_operations SET state = ?, result = ? WHERE id = ?').bind('uncertain',JSON.stringify({error:errorInfo(e)}),id).run();
    throw e;
  }
}
async function handle(request,env) {
  const url=new URL(request.url);
  const user=request.headers.get('oai-authenticated-user-id');
  if(url.pathname==='/favicon.ico') return new Response(null,{status:204});
  if(!user) {
    if(url.pathname.startsWith('/api/')) return json({ok:false,error:{category:'authentication',message:'ChatGPTでサインインしてください。'}},401);
    return new Response('サインインが必要です。',{status:401,headers:noStore});
  }
  if(url.pathname==='/' && request.method==='GET') {
    const nonce=crypto.randomUUID().replace(/-/g,'');
    return new Response(HTML.replaceAll('__NONCE__',nonce),{headers:{...noStore,'Content-Type':'text/html; charset=utf-8','Content-Security-Policy':"default-src 'self'; script-src 'nonce-"+nonce+"'; style-src 'nonce-"+nonce+"'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'self' https://chatgpt.com"}});
  }
  if(url.pathname==='/api/status' && request.method==='GET') {
    const page=Math.max(1,Math.min(10,Number(url.searchParams.get('page'))||1));
    const key=user+':'+page;
    let entry=pendingReads.get(key);
    if(!entry || Date.now()-entry.at>60000) {
      if(pendingReads.size>32)pendingReads.clear();
      entry={at:Date.now(),promise:loadStatus(env,page)};pendingReads.set(key,entry);
      entry.promise.catch(()=>pendingReads.delete(key));
    }
    return json(await entry.promise);
  }
  if(url.pathname==='/api/run' && request.method==='GET') {
    const id=url.searchParams.get('id');
    if(!/^\d{1,16}$/.test(id||'')) return json({ok:false,error:{message:'実行IDが不正です。'}},400);
    return json(await loadRunDetail(id,env));
  }
  if(url.pathname==='/api/operate' && request.method==='POST') {
    const response=await operate(request,env,user);
    pendingReads.clear();
    return response;
  }
  if(url.pathname==='/api/operations' && request.method==='GET') {
    if(!env.DB)return json({available:false,items:[]});
    const rows=await env.DB.prepare('SELECT id, action, state, created_at FROM dashboard_operations WHERE owner_id = ? ORDER BY created_at DESC LIMIT 20').bind(user).all();
    return json({available:true,items:rows.results});
  }
  return json({ok:false,error:{message:'Not found'}},404);
}
export default {
  async fetch(request,env) {
    try{return await handle(request,env);}catch(e){return json({ok:false,error:errorInfo(e)},e.status || 502);}
  }
};
